import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.CCCdsIgc.js";const _=JSON.parse('{"title":"沙箱任务","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sandbox.md","filePath":"guide/sandbox.md"}'),o={name:"guide/sandbox.md"};function l(i,t,n,s,c,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="沙箱任务" tabindex="-1">沙箱任务 <a class="header-anchor" href="#沙箱任务" aria-label="Permalink to &quot;沙箱任务&quot;">​</a></h1><p>想让 AI 在<strong>不打扰你</strong>的情况下长时间写代码、跑测试？打开沙箱任务：它在你电脑上的一次性 Docker 容器里干活，中途不弹确认，做完推到一个新分支并建 PR。</p><h2 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h2><ul><li>IT 在安全中心打开了「开发者工具」和「<strong>沙箱任务</strong>」；</li><li>电脑装了 Docker Desktop（WSL 里的 Docker 只要认 <code>docker</code> 命令也行）；</li><li>工作区是一个 GitHub 仓库。</li></ul><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><ol><li>办事输入框下方点「<strong>沙箱</strong>」打开；</li><li>第一次发话时会准备容器（复制仓库进去），右侧仓库面板显示进度和任务分支 <code>flyknit/…</code>；</li><li>之后读写文件、执行命令、装依赖、跑测试都在容器里，不弹确认，也不会改你本机的文件；</li><li>AI 做完用 <code>create_pull_request</code> 把任务分支推上去建 PR，然后按<a href="./developer.html#盯-pr">盯 PR</a> 的规则跟进 CI。</li></ol><h2 id="能离开容器的只有一条路" tabindex="-1">能离开容器的只有一条路 <a class="header-anchor" href="#能离开容器的只有一条路" aria-label="Permalink to &quot;能离开容器的只有一条路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>只推任务分支</td><td>只能推 <code>flyknit/</code> 开头的分支，不能推默认分支，不能强推</td></tr><tr><td>CI 配置</td><td>默认不许改（IT 可以打开）</td></tr><tr><td>改动数量</td><td>一次超过 2000 个文件不自动推</td></tr><tr><td>钩子</td><td>仓库里的 git 钩子不会在你的电脑上执行</td></tr><tr><td>凭证</td><td>推送用你电脑上的 git 登录，令牌不进容器</td></tr></tbody></table><p>读到疑似「提示词注入」的内容后，推送这一步会改为先问你。</p><h2 id="关闭沙箱" tabindex="-1">关闭沙箱 <a class="header-anchor" href="#关闭沙箱" aria-label="Permalink to &quot;关闭沙箱&quot;">​</a></h2><p>再点一次「沙箱」，或仓库面板里「结束沙箱」。会删除容器，<strong>没推送出去的改动会丢失</strong>，已经建好的 PR 不受影响。</p>',11)])])}const p=e(o,[["render",l]]);export{_ as __pageData,p as default};
